import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

// Push subscriptions and the reminders scheduled for them. A device is one installed copy of the app;
// its id is a random secret generated by the app, so knowing it is what authorizes changes.

export type PushSubscriptionJSON = {
  endpoint: string;
  keys: { p256dh: string; auth: string };
};

export type Reminder = {
  /** Stable per device, e.g. "item-3-soon". */
  id: string;
  /** Unix time in milliseconds. */
  at: number;
  title: string;
  body: string;
  /** Path in the app to open when the notification is tapped. */
  url: string;
};

export type DueReminder = Reminder & { deviceId: string; subscription: PushSubscriptionJSON; attempts: number };

export type Store = ReturnType<typeof openStore>;

export function openStore(path: string) {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`
    PRAGMA journal_mode = WAL;
    PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS device (
      id TEXT PRIMARY KEY,
      subscription TEXT NOT NULL,
      updated_at INTEGER NOT NULL
    );
    CREATE TABLE IF NOT EXISTS reminder (
      device_id TEXT NOT NULL REFERENCES device (id) ON DELETE CASCADE,
      id TEXT NOT NULL,
      at INTEGER NOT NULL,
      title TEXT NOT NULL,
      body TEXT NOT NULL,
      url TEXT NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      PRIMARY KEY (device_id, id)
    );
    CREATE INDEX IF NOT EXISTS reminder_at ON reminder (at);
  `);

  const upsertDevice = db.prepare(
    `INSERT INTO device (id, subscription, updated_at) VALUES (?, ?, ?)
     ON CONFLICT (id) DO UPDATE SET subscription = excluded.subscription, updated_at = excluded.updated_at`
  );
  const clearReminders = db.prepare('DELETE FROM reminder WHERE device_id = ?');
  const insertReminder = db.prepare(
    'INSERT INTO reminder (device_id, id, at, title, body, url) VALUES (?, ?, ?, ?, ?, ?)'
  );
  const deleteDeviceStmt = db.prepare('DELETE FROM device WHERE id = ?');
  const selectDue = db.prepare(
    `SELECT r.device_id, r.id, r.at, r.title, r.body, r.url, r.attempts, d.subscription
     FROM reminder r JOIN device d ON d.id = r.device_id
     WHERE r.at <= ? ORDER BY r.at LIMIT ?`
  );
  const deleteReminderStmt = db.prepare('DELETE FROM reminder WHERE device_id = ? AND id = ?');
  const bumpAttempts = db.prepare('UPDATE reminder SET attempts = attempts + 1 WHERE device_id = ? AND id = ?');
  const countDevices = db.prepare('SELECT COUNT(*) AS n FROM device');

  return {
    /** Saves the device's subscription and replaces its whole reminder schedule. */
    replaceSchedule(deviceId: string, subscription: PushSubscriptionJSON, reminders: Reminder[], now = Date.now()) {
      db.exec('BEGIN');
      try {
        upsertDevice.run(deviceId, JSON.stringify(subscription), now);
        clearReminders.run(deviceId);
        for (const r of reminders) insertReminder.run(deviceId, r.id, r.at, r.title, r.body, r.url);
        db.exec('COMMIT');
      } catch (error) {
        db.exec('ROLLBACK');
        throw error;
      }
    },

    deleteDevice(deviceId: string) {
      deleteDeviceStmt.run(deviceId);
    },

    due(now: number, limit = 500): DueReminder[] {
      return selectDue.all(now, limit).map((row) => ({
        deviceId: row.device_id as string,
        id: row.id as string,
        at: row.at as number,
        title: row.title as string,
        body: row.body as string,
        url: row.url as string,
        attempts: row.attempts as number,
        subscription: JSON.parse(row.subscription as string) as PushSubscriptionJSON,
      }));
    },

    /** A reminder is deleted once delivered, so it can't be sent twice. */
    markSent(deviceId: string, id: string) {
      deleteReminderStmt.run(deviceId, id);
    },

    markFailed(deviceId: string, id: string) {
      bumpAttempts.run(deviceId, id);
    },

    deviceCount(): number {
      return countDevices.get()!.n as number;
    },

    close() {
      db.close();
    },
  };
}
